local frameRates = {30, 45, 60, 120}
local texts = {"30", "45", "60", "120"}




-- ========================================================


function DebugBoxFrameRateButton:__init(debugBox_, frameRateButton_)

    self.debugBox = debugBox_ -- DebugBox
    self.frameRateButton = frameRateButton_ -- Button

    local comps = self.frameRateButton:GetComponentsInChildren(typeof(TMP_Text),true) -- 包含自己

    self.frameRateButtonText = nil
    for i=0, comps.Length-1 do 
        local comp = comps[i]

        self.frameRateButtonText = comp -- TMP_Text
        break
    end
    assert(self.frameRateButtonText)

    self.frameRateButton.onClick:AddListener(function()
        self:OnPress()
    end)


    self.frameRateIdx = 1 -- int,  Second element

    -- !!! 此处不能 Set(), 会覆盖 白塔主流程的 帧率设置
    --self:Set()
end



function DebugBoxFrameRateButton:__delete()
end



-- =========================================== Self ================================================ --


function DebugBoxFrameRateButton:Restart()
    self.frameRateIdx = 1
    --self:Set()
end


function DebugBoxFrameRateButton:OnPress()
    self.frameRateIdx = self.frameRateIdx + 1
    if self.frameRateIdx > #frameRates then
        self.frameRateIdx = 1
    end
    self:Set()
end


function DebugBoxFrameRateButton:Set()

    print("koko  DebugBoxFrameRateButton:Set")

    Application.targetFrameRate = frameRates[self.frameRateIdx]
    self.frameRateButtonText.text = "Frame: " .. texts[self.frameRateIdx]
end





return DebugBoxFrameRateButton

